INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(36411, 'Romans 16:6', 'Romans', 16, 6, 'مریم ته چې ستاسو دپاره یې ډېر زحمت ویستلی دی، سلام ووایئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_6.mp3', '', 1761754199, 1761754199),
(36412, 'Romans 16:7', 'Romans', 16, 7, 'اندرونیکاس او یونیا ته چې زما وطنداران دي او زما سره په زندان کې وو، سلامونه ووایئ. هغوی په رسولانو کې مشهور خلک دي او زما نه مخکې یې په مسیح باندې ایمان راوړی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_7.mp3', '', 1761754199, 1761754199),
(36413, 'Romans 16:8', 'Romans', 16, 8, 'همدارنګه امپلیاتوس ته چې په څښتن عیسی مسیح کې زما ګران ملګری دی، سلام ووایئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_8.mp3', '', 1761754199, 1761754199),
(36414, 'Romans 16:9', 'Romans', 16, 9, 'اوربانوس ته چې د مسیح په خدمت کې زمونږ ملګری دی او استاخیس ته چې په ما باندې ګران دی، سلامونه ووایئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_9.mp3', '', 1761754199, 1761754199),
(36415, 'Romans 16:10', 'Romans', 16, 10, 'اپلیس ته چې وفاداري یې مسیح ته ثابته شوې ده او د ارستبولوس کورنۍ ته زما سلامونه ووایئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_10.mp3', '', 1761754199, 1761754199),
(36416, 'Romans 16:11', 'Romans', 16, 11, 'زما وطندار هیرودیون او نرکیسوس د کورنۍ ایماندارانو ته سلامونه ووایئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_11.mp3', '', 1761754199, 1761754199),
(36417, 'Romans 16:12', 'Romans', 16, 12, 'تریفینا او تریفوسا ته چې د څښتن خدمت کوي او ګرانې پرسیس ته چې د څښتن دپاره یې ډېر زحمت ویستلی دی، سلامونه ووایئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_12.mp3', '', 1761754199, 1761754199),
(36418, 'Romans 16:13', 'Romans', 16, 13, 'روفس ته چې د څښتن له خوا غوره شوی دی او د هغه مور ته چې ماته هم لکه د مور په شان ده، سلامونه ووایئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_13.mp3', '', 1761754199, 1761754199),
(36419, 'Romans 16:14', 'Romans', 16, 14, 'اسونکریتوس، فلیګون، هرمیس، پتروباس، هرماس او نورو خویندو او ورونو ته چې د هغوی سره دي، سلامونه ووایئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_14.mp3', '', 1761754199, 1761754199),
(36420, 'Romans 16:15', 'Romans', 16, 15, 'فیلولوګاس، جولیه، نیریاس او د هغه خور او اولیمپیاس او ټولو ایماندارانو ته چې د هغوی سره دي، سلامونه ووایئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_15.mp3', '', 1761754199, 1761754199),
(36421, 'Romans 16:16', 'Romans', 16, 16, 'یو بل ته سلام ووایئ او په پاکه مینه یو بل ښکل کړئ. د مسیح ټولې کلیساګانې تاسو ته سلام وایي. وروستنۍ لارښوونې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_16.mp3', '', 1761754199, 1761754199),
(36422, 'Romans 16:17', 'Romans', 16, 17, 'ای خویندو او ورونو! زه ستاسو نه غوښتنه کوم چې هغو خلکو ته مو پام وي چې بې‌اتفاقي رامنځته کوي او نور بې‌لارې کوي او د هغه تعلیم په خلاف دي چې تاسو حاصل کړی دی. د هغوی څخه ځان لېرې وساتئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_17.mp3', '', 1761754199, 1761754199),
(36423, 'Romans 16:18', 'Romans', 16, 18, 'ځکه چې داسې خلک زمونږ د څښتن مسیح خدمت نه کوي، بلکې د خپلې خېټې دپاره کار کوي او په خوږو خبرو او غوړه مالۍ سره ساده خلک غولوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_18.mp3', '', 1761754199, 1761754199),
(36424, 'Romans 16:19', 'Romans', 16, 19, 'ځکه چې د څښتن څخه ستاسو اطاعت کول ټولو خلکو ته معلوم دي او له همدې امله زه ستاسو په خاطر خوشحاله یم. خو زه غواړم چې تاسو په ښه کار کې هوښیار اوسئ او په بد کار کې بې‌ګناه اوسئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_19.mp3', '', 1761754199, 1761754199),
(36425, 'Romans 16:20', 'Romans', 16, 20, 'خدای چې د سلامتۍ سرچینه ده، هغه به زر شیطان ستاسو د پښو لاندې ټوټې ټوټې کړي. په تاسو باندې دې زمونږ د څښتن عیسی مسیح فضل وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_20.mp3', '', 1761754199, 1761754199),
(36426, 'Romans 16:21', 'Romans', 16, 21, 'زما همکار تیموتاوس او همدارنګه زما وطنداران لوسیوس او یاسون او سوسیپاتوس هم تاسو ته سلامونه وایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_21.mp3', '', 1761754199, 1761754199),
(36427, 'Romans 16:22', 'Romans', 16, 22, 'زه ترتیوس د پولوس منشي د دې لیک لیکونکی هم تاسو ته د څښتن په نوم سلامونه وایم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_22.mp3', '', 1761754199, 1761754199),
(36428, 'Romans 16:23', 'Romans', 16, 23, 'ګایوس چې زما او د هغه په کور کې د ټولې کلیسا کوربه دی، تاسو ته سلامونه وایي او د ښار خزانه دار اراستوس او زمونږ ورور کوارتس هم تاسو ته سلامونه وایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_23.mp3', '', 1761754199, 1761754199),
(36429, 'Romans 16:24', 'Romans', 16, 24, '[زمونږ د څښتن عیسی مسیح فضل دې په تاسو ټولو باندې وي. امین.] د پولوس اخرنۍ دعا', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_24.mp3', '', 1761754199, 1761754199),
(36430, 'Romans 16:25', 'Romans', 16, 25, 'اوس دې خدای ته جلال وي چې کولای شي تاسو په ایمان کې د عیسی مسیح د زیري له مخې چې زه یې اعلانوم او د هغه راز د څرګندولو له مخې چې د پېړیو پېړیو راهیسې پټ پاتې ؤ، قوي کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_25.mp3', '', 1761754199, 1761754199),
(36431, 'Romans 16:26', 'Romans', 16, 26, 'اوس دا حقیقت د پیغمبرانو د لیکنو په وسیله څرګند شوی دی او د ابدي خدای د حکم له مخې د دنیا ټولو قومونو ته ښکاره شوی دی، ترڅو هغوی ایمان راوړي او د هغه اطاعت وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_26.mp3', '', 1761754199, 1761754199),
(36432, 'Romans 16:27', 'Romans', 16, 27, 'هغه واحد او یوازېني خدای ته دې چې په هرڅه پوهیږي د عیسی مسیح په وسیله تل ترتله جلال وي. امین.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_27.mp3', '', 1761754199, 1761754199),
(36433, 'James 1:1', 'James', 1, 1, 'د خدای او د څښتن عیسی مسیح د خدمتګار یعقوب له خوا دې د اسراییلو دولس قبیلو ته چې په ټوله نړۍ کې خواره واره شوي دي، سلام وي. ایمان او حکمت', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_1.mp3', '', 1761754199, 1761754199),
(36434, 'James 1:2', 'James', 1, 2, 'ای زما خویندو او ورونو! هرکله چې تاسو د ډول ډول ازمېښتونو سره مخامخ کېږئ نو هغه یوه خوشحالي وګڼئ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_2.mp3', '', 1761754199, 1761754199),
(36435, 'James 1:3', 'James', 1, 3, 'ځکه تاسو پوهېږئ چې دا ستاسو د ایمان په ازمېښت کې ستاسو صبر او زغم زیاتوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_3.mp3', '', 1761754199, 1761754199),
(36436, 'James 1:4', 'James', 1, 4, 'کله چې ستاسو صبر او زغم نور هم زیات شي، نو تاسو به کامل او بې‌عیبه انسانان شئ او د هېڅ شي کمی به په تاسو کې نه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_4.mp3', '', 1761754199, 1761754199),
(36437, 'James 1:5', 'James', 1, 5, 'خو که په تاسو کې په چا کې د حکمت کمی وي، نو هغه دې د خدای څخه وغواړي چې هغه یې د سخاوت له مخې او بې له دې چې څوک ملامته کړي هرچا ته ورکوي، نو هغه ته به هم ورکړل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_5.mp3', '', 1761754199, 1761754199),
(36438, 'James 1:6', 'James', 1, 6, 'خو کله چې څوک کوم شی غواړي، نو هغه دې د ایمان سره وغواړي او هېڅ شک دې نه کوي، ځکه چې شک کوونکی د بحر د هغو څپو په شان دی چې د باد په وسیله اخوا دې خوا غورځول کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_6.mp3', '', 1761754199, 1761754199),
(36439, 'James 1:7', 'James', 1, 7, 'داسې سړی دې په دې تمه نه اوسي چې ماته به د څښتن څخه کوم څه لاسته راشي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_7.mp3', '', 1761754199, 1761754199),
(36440, 'James 1:8', 'James', 1, 8, 'ځکه چې شکمن سړی په خپلو کارونو کې ټینګ ولاړ نه وي. غریب خلک او شتمن خلک', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_8.mp3', '', 1761754199, 1761754199),
(36441, 'James 1:9', 'James', 1, 9, 'غریب ورور دې د خدای په وړاندې په خپلې سرلوړۍ باندې ویاړ وکړي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_9.mp3', '', 1761754199, 1761754199),
(36442, 'James 1:10', 'James', 1, 10, 'او همدارنګه شتمن ورور دې په خپلې عاجزۍ باندې چې د خدای له خوا ده ویاړ وکړي، ځکه چې هغه به د واښو د ګل په شان له منځه لاړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_10.mp3', '', 1761754199, 1761754199),
(36443, 'James 1:11', 'James', 1, 11, 'ځکه کله چې لمر د خپلې سوځوونکې ګرمۍ سره راوخېژي نو واښه وچ کړي، ګلان یې ورژیږي او ښایست یې له منځه لاړ شي. نو همداسې به شتمن سړی هم د خپل کاروبار سره له منځه لاړ شي. ازمېښتونه او وسوسې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_11.mp3', '', 1761754199, 1761754199),
(36444, 'James 1:12', 'James', 1, 12, 'بختور دی هغه څوک چې د ازمېښت په وخت کې ټینګ پاتې شي، ځکه کله چې هغه د داسې ازمېښت څخه بریالی تېر شي، نو د ژوندون تاج به چې خدای د هغو خلکو سره چې ورباندې ګران دی وعده کړې ده، تر‌لاسه کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_12.mp3', '', 1761754199, 1761754199),
(36445, 'James 1:13', 'James', 1, 13, 'څوک چې وسوسه کیږي، نو هغه باید دا ونه وایي: «خدای زه وسوسه کړی یم،» ځکه چې خدای د هېڅ ډول بدۍ په وسیله نه وسوسه کیږي او نه هم څوک وسوسه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_13.mp3', '', 1761754199, 1761754199),
(36446, 'James 1:14', 'James', 1, 14, 'خو یو کس هغه وخت وسوسه کیږي چې کله هغه د خپلو نفساني غوښتنو په وسیله وهڅول شي او په دام کې راونیول شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_14.mp3', '', 1761754199, 1761754199),
(36447, 'James 1:15', 'James', 1, 15, 'بیا د هغه نفساني غوښتنې د ګناه د راپیدا کېدلو سبب کیږي او کله چې ګناه خپل وروستي حد ته ورسیږي، نو د مرګ سبب ګرځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_15.mp3', '', 1761754199, 1761754199),
(36448, 'James 1:16', 'James', 1, 16, 'ای زما ګرانو خویندو او ورونو! ونه غولېږئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_16.mp3', '', 1761754199, 1761754199),
(36449, 'James 1:17', 'James', 1, 17, 'ټول ښه او کامل نعمتونه مونږ ته د خدای له خوا چې د لمر، سپوږمۍ او ستورو پیدا کوونکی دی، راځي. هغه نه بدلېدونکی دی او نه د سیوري په شان ګرځي او راګرځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_17.mp3', '', 1761754199, 1761754199),
(36450, 'James 1:18', 'James', 1, 18, 'هغه مونږ د خپلې ارادې او رښتیني کلام په وسیله پیدا کړو، ترڅو د هغه په ټولو مخلوقاتو کې لکه د لومړني حاصل مېوه واوسو. د کلام اورېدل او په هغه باندې عمل کول', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_18.mp3', '', 1761754199, 1761754199),
(36451, 'James 1:19', 'James', 1, 19, 'نو ای ګرانو خویندو او ورونو! دا یاد ساتئ چې هرڅوک باید په اورېدلو کې تېز، په خبرو کې ورو او په قهر کې سوړ اوسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_19.mp3', '', 1761754199, 1761754199),
(36452, 'James 1:20', 'James', 1, 20, 'ځکه کله چې څوک په قهر شي هغه نه شي کولای چې د خدای عادلانه مقصدونه پوره کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_20.mp3', '', 1761754199, 1761754199),
(36453, 'James 1:21', 'James', 1, 21, 'له دې امله تاسو د ټولو غیر اخلاقي کارونو او ټولو بدیو څخه لاس واخلئ او په عاجزۍ سره هغه کلام قبول کړئ چې ستاسو په زړونو کې کرل شوی او کولای شي تاسو ته خلاصون درکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_21.mp3', '', 1761754199, 1761754199),
(36454, 'James 1:22', 'James', 1, 22, 'نو تاسو باید د هغه په کلام عمل وکړئ او یوازې په اورېدلو سره یې خپل ځانونه مه غولوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_22.mp3', '', 1761754199, 1761754199),
(36455, 'James 1:23', 'James', 1, 23, 'ځکه څوک چې کلام ته غوږ نیسي او عمل پرې نه کوي، نو هغه د هغه سړي په شان دی چې خپل مخ په ایینه کې ویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_23.mp3', '', 1761754199, 1761754199),
(36456, 'James 1:24', 'James', 1, 24, 'کله چې هغه خپل ځان وویني او لاړ شي، نو سمدلاسه دا هېر کړي چې څېره یې څنګه وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_24.mp3', '', 1761754199, 1761754199),
(36457, 'James 1:25', 'James', 1, 25, 'خو که چېرې څوک کامل او ازادي بخښونکي شریعت ته په غور سره وګوري او په هغه باندې عمل وکړي او څه چې واوري او هغه هېر نه کړي، نو خدای به د هغه په ټولو کارونو کې برکت واچوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_25.mp3', '', 1761754199, 1761754199),
(36458, 'James 1:26', 'James', 1, 26, 'که څوک خپل ځان دینداره ګڼي او خپله ژبه په واک کې نه ساتي، نو هغه خپل ځان غولوي او دینداري یې هېڅ ګټه نه لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_26.mp3', '', 1761754199, 1761754199),
(36459, 'James 1:27', 'James', 1, 27, 'د پلار خدای په نظر کې سوچه او بې‌عیبه دینداري دا ده چې په یتیمانو او کونډو باندې د مصیبت په وخت کې پام وکړو او پرې نه ږدو چې دا نړۍ مو فاسد کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/james1_verse_27.mp3', '', 1761754199, 1761754199),
(36460, 'Revelation 14:1', 'Revelation', 14, 1, 'بیا ما وکتل او ومې لیدل چې د صهیون په غره باندې وری ولاړ ؤ او یو لک او څلورڅلوېښت زره کسان ورسره وو چې په تندیو باندې یې د هغه نوم او د هغه د پلار نوم لیکل شوی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_1.mp3', '', 1761754199, 1761754199),
(36461, 'Revelation 14:2', 'Revelation', 14, 2, 'ما د اسمان نه یو اواز واورېد چې د تېزو اوبو د غرهار او د تندر د لوړ اواز په شان ؤ. کوم اواز چې ما واورېد هغه داسې ؤ لکه چنګ غږوونکي چې خپل چنګونه غږوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_2.mp3', '', 1761754199, 1761754199),
(36462, 'Revelation 14:3', 'Revelation', 14, 3, 'هغوی د تخت او د څلورو اسماني موجوداتو او مشرانو په مخکې یوه نوې سندره وویله. هېچا دا سندره زده کولای نه شوه، بې له هغو یو لک او څلورڅلوېښت زره کسانو څخه چې د ټولې نړۍ څخه بېرته په بیه اخیستل شوي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_3.mp3', '', 1761754199, 1761754199),
(36463, 'Revelation 14:4', 'Revelation', 14, 4, 'دا هغه کسان دي چې ځانونه یې د جنسي اړیکو نه لېرې ساتلي دي. هر‌چېرته چې وری ځي، نو هغوی ورپسې روان وي. هغوی د خدای او وري دپاره د انسانانو له منځ نه د لومړني حاصل په توګه په بیه اخیستل شوي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_4.mp3', '', 1761754199, 1761754199),
(36464, 'Revelation 14:5', 'Revelation', 14, 5, 'هغوی هېڅ دروغ نه وایي او بې‌عیبه دي. د درېو فرښتو پیغامونه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_5.mp3', '', 1761754199, 1761754199),
(36465, 'Revelation 14:6', 'Revelation', 14, 6, 'بیا ما بله فرښته ولیدله چې په اسمان کې الوتله، هغې د ځمکې په مخ اوسېدونکو، هر ملت، هرې قبیلې، هرې ژبې او هر قوم ته تلپاتې زېری ورکاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_6.mp3', '', 1761754199, 1761754199),
(36466, 'Revelation 14:7', 'Revelation', 14, 7, 'هغې په لوړ اواز نارې وهلې: «د خدای څخه ووېرېږئ او هغه ته جلال ورکړئ، ځکه چې هغه وخت رارسېدلی دی چې هغه به قضاوت کوي. د هغه عبادت وکړئ چې اسمان، ځمکه، بحر او د اوبو چینې یې پیدا کړي دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_7.mp3', '', 1761754199, 1761754199),
(36467, 'Revelation 14:8', 'Revelation', 14, 8, 'د هغې نه وروسته دوهمه فرښته راغله او نارې یې ووهلې: «راولوېد، هغه لوی بابل راولوېد، ځکه چې ټول قومونه د هغې د زناکارۍ د شهوت د نشې تر اغیزې لاندې وو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_8.mp3', '', 1761754199, 1761754199),
(36468, 'Revelation 14:9', 'Revelation', 14, 9, 'بیا د هغوی پسې درېمه فرښته راغله او په لوړ اواز یې نارې ووهلې: «څوک چې هغه ځناور او د هغه مجسمې ته عبادت کوي او مني چې د هغه نښه په خپل تندي یا لاس باندې ولري،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_9.mp3', '', 1761754199, 1761754199),
(36469, 'Revelation 14:10', 'Revelation', 14, 10, 'هغه به د خدای د قهر او غضب شراب وڅښي، هغه ټینګ شراب چې هغه د خپل قهر په پیاله کې اچولي دي. هغوی به د سپېڅلو فرښتو او وري په حضور کې په اور او د ګوګړو په لمبو کې عذاب وویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_10.mp3', '', 1761754199, 1761754199),
(36470, 'Revelation 14:11', 'Revelation', 14, 11, 'د هغوی د عذاب لوګی به د تل دپاره راپورته کیږي او هر هغه څوک چې هغه ځناور او د هغه مجسمې ته عبادت کوي او یا د هغه د نوم نښه ورباندې لګېدلې وي، نو هغوی به نه د شپې او نه د ورځې ارام ولري.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_11.mp3', '', 1761754199, 1761754199),
(36471, 'Revelation 14:12', 'Revelation', 14, 12, 'دا په دې معنی ده چې د خدای د خلکو دپاره صبر او زغم په کار دی چې د هغه حکمونه ومني او عیسی ته وفادار پاتې شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_12.mp3', '', 1761754199, 1761754199),
(36472, 'Revelation 14:13', 'Revelation', 14, 13, 'بیا ما د اسمان نه یو اواز واورېد چې ویل یې:«دا ولیکه، بختور دي هغه خلک چې له همدا‌اوس نه په څښتن باندې په ایمان کې مړه کیږي!» روح القدس وایي: «هو، هغوی به د خپلو زحمتونو نه په ارام وي، ځکه چې د هغوی نېک عملونه به ورسره وي.» د ځمکې د حاصل لو کول', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_13.mp3', '', 1761754199, 1761754199),
(36473, 'Revelation 14:14', 'Revelation', 14, 14, 'بیا ما وکتل او ومې لیدل چې یوه سپینه ورېځ راښکاره شوه او په هغې باندې یو څوک ناست ؤ چې د انسان په شان ؤ. د هغه په سر باندې د سرو زرو تاج ؤ او په لاس کې یې تېره لور ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_14.mp3', '', 1761754199, 1761754199),
(36474, 'Revelation 14:15', 'Revelation', 14, 15, 'بیا یوه بله فرښته د خدای د کور نه راووتله او هغه کس ته یې چې په ورېځې باندې ناست ؤ، په لوړ اواز غږ وکړ: «خپل لور دې راواخله او ورېبه، ځکه چې د لو وخت رارسېدلی دی او د ځمکې فصل پوخ او تیار دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_15.mp3', '', 1761754199, 1761754199),
(36475, 'Revelation 14:16', 'Revelation', 14, 16, 'نو هغه کس چې په ورېځې باندې ناست ؤ خپل لور یې ځمکې ته واچاوه او فصل ورېبل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_16.mp3', '', 1761754199, 1761754199),
(36476, 'Revelation 14:17', 'Revelation', 14, 17, 'بیا یوه بله فرښته د خدای له کور نه چې په اسمان کې ؤ، راووتله او د هغې په لاس کې هم یو تېره لور ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_17.mp3', '', 1761754199, 1761754199),
(36477, 'Revelation 14:18', 'Revelation', 14, 18, 'بیا یوه بله فرښته د قربانۍ د ځای نه راووتله، هغه د قربانۍ د ځای د اور مسوولیت درلود او هغې فرښتې ته یې چې تېره لور ورسره ؤ، په لوړ اواز نارې کړې او ویې ویل: «د خپل لور نه کار واخله او د نړۍ د تاکونو نه د انګورو وږي راټول کړه، ځکه چې انګور یې پاخه دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_18.mp3', '', 1761754199, 1761754199),
(36478, 'Revelation 14:19', 'Revelation', 14, 19, 'نو هغې فرښتې خپل لور ورواچاوه او د دې نړۍ د تاکونو انګور یې راټول کړل او هغه یې د خدای د قهر او غضب د شربت ویستلو په لوی خم کې واچول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_19.mp3', '', 1761754199, 1761754199),
(36479, 'Revelation 14:20', 'Revelation', 14, 20, 'انګور یې د اورشلیم د ښار نه دباندې د شربت ویستلو په خم کې تر پښو لاندې وزبېښل او د خم نه د وینو سېلاب جاري شو او دا وینې لکه د اس د قیضو په اندازه لوړې وې او د درې سوه کیلومترو په اندازه لېرې لاړلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation14_verse_20.mp3', '', 1761754199, 1761754199),
(36480, 'Mark 1:1', 'Mark', 1, 1, 'دا د خدای د زوی عیسی مسیح د زېري پیل دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_1.mp3', '', 1761754199, 1761754199),
(36481, 'Mark 1:2', 'Mark', 1, 2, 'هغه داسې پیل شو لکه څنګه چې د اشعیا نبي په کتاب کې لیکل شوي دي: «ګوره، زه به خپل استازی ستا څخه مخکې ولېږم چې ستا دپاره لاره تیاره کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_2.mp3', '', 1761754199, 1761754199),
(36482, 'Mark 1:3', 'Mark', 1, 3, 'یو څوک چیغې وهي دښته کې کړئ تیاره د څښتن دپاره لاره لاره کړئ سمه د هغه دپاره» د تعمید غسل ورکوونکي یحیی وعظ (متي ۳‏:‌۱‌‏-‌۱۲ او لوقا ۳‏:‌۱‌‏-‌۱۸ او یوحنا ۱‏:‌۱۹‌‏-‌۲۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_3.mp3', '', 1761754199, 1761754199),
(36483, 'Mark 1:4', 'Mark', 1, 4, 'د تعمید ورکوونکی یحیی په دښته کې راښکاره شو او وعظ یې کاوه چې خلک باید د خپلو ګناهونو د بخښنې په خاطر توبه وباسي او د تعمید غسل واخلي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_4.mp3', '', 1761754199, 1761754199),
(36484, 'Mark 1:5', 'Mark', 1, 5, 'د ټولې یهودیې خلک او د اورشلیم ټول اوسېدونکي یحیی ته راتلل. هغوی په خپلو ګناهونو باندې اقرار کاوه او د اردن په سیند کې یې د هغه په لاس د تعمید غسل اخیسته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_5.mp3', '', 1761754199, 1761754199),
(36485, 'Mark 1:6', 'Mark', 1, 6, 'یحیی داسې کالي اغوستل چې د اوښ د وړیو څخه جوړ شوي وو او د څرمنې کمربند به یې له ملا تړلو او ملخان او ځنګلي شات به یې خوړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_6.mp3', '', 1761754199, 1761754199),
(36486, 'Mark 1:7', 'Mark', 1, 7, 'هغه اعلان کاوه او ویل به یې: «زما څخه وروسته چې کوم څوک راروان دی، هغه زما څخه ډېر زورور دی، زه د دې لایق هم نه یم چې ټیټ شم او د هغه د څپلیو تسمې خلاصې کړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_7.mp3', '', 1761754199, 1761754199),
(36487, 'Mark 1:8', 'Mark', 1, 8, 'زه تاسو ته په اوبو باندې د تعمید غسل درکوم، خو هغه به درته په روح القدس د تعمید غسل درکړي.» د عیسی د تعمید غسل او د هغه ازمېښت (متي ۳‏:‌۱۳ ‏- ۴‏:‌۱۱ او لوقا ۳‏:‌۲۱‌‏-‌۲۲، ۴‏:‌۱‌‏-‌۱۳)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_8.mp3', '', 1761754199, 1761754199),
(36488, 'Mark 1:9', 'Mark', 1, 9, 'داسې وشول چې په هماغو ورځو کې عیسی د جلیل د ولایت د ناصرې د ښار څخه راغی او د اردن په سیند کې یې د یحیی په لاس د تعمید غسل واخیست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_9.mp3', '', 1761754199, 1761754199),
(36489, 'Mark 1:10', 'Mark', 1, 10, 'کله چې عیسی د اوبو ‎څخه راووت، نو ویې لیدل چې ناڅاپه اسمان سوری شو او روح القدس د کوترې په شکل په هغه باندې رانازل شو', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_10.mp3', '', 1761754199, 1761754199),
