(36491, 'Mark 1:12', 'Mark', 1, 12, 'سمدلاسه روح القدس هغه دښتې ته په تللو مجبور کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_12.mp3', '', 1761754199, 1761754199),
(36492, 'Mark 1:13', 'Mark', 1, 13, 'هغه څلوېښت ورځې په دښته کې ؤ او شیطان د هغه ازمېښت کاوه. عیسی په هغه ځای کې ؤ چېرته چې ځنګلي ځناور وو او فرښتو د هغه خدمت کاوه. عیسی څلورو ماهيګیرانو ته بلنه ورکوي (متي ۴‏:‌۱۲‌‏-‌۲۲ او لوقا ۴‏:‌۱۴‌‏-‌۱۵، ۵‏:‌۱‌‏-‌۱۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_13.mp3', '', 1761754199, 1761754199),
(36493, 'Mark 1:14', 'Mark', 1, 14, 'کله چې یحیی په زندان کې واچول شو، نو عیسی جلیل ته لاړ او هلته یې د خدای زېری اعلاناوه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_14.mp3', '', 1761754199, 1761754199),
(36494, 'Mark 1:15', 'Mark', 1, 15, 'او ویل یې: «اوس هغه وخت رارسېدلی دی او د خدای پاچاهي رانژدې شوې ده. توبه وباسئ او په زېري باندې ایمان راوړئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_15.mp3', '', 1761754199, 1761754199),
(36495, 'Mark 1:16', 'Mark', 1, 16, 'کله چې عیسی د جلیل د بحیرې په غاړه ګرځېده، نو شمعون او د هغه ورور اندریاس یې ولیدل. هغوی په بحیره کې جال اچاوه، ځکه چې هغوی ماهیګیران وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_16.mp3', '', 1761754199, 1761754199),
(36496, 'Mark 1:17', 'Mark', 1, 17, 'عیسی هغوی ته وویل: «ما پسې راځئ او زه به تاسو ته وښایم چې څنګه د ماهیانو په ځای انسانان ونیسئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_17.mp3', '', 1761754199, 1761754199),
(36497, 'Mark 1:18', 'Mark', 1, 18, 'هغوی سمدلاسه خپل جالونه پرېښودل او هغه پسې روان شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_18.mp3', '', 1761754199, 1761754199),
(36498, 'Mark 1:19', 'Mark', 1, 19, 'کله چې عیسی لږ وړاندې لاړ، نو هغه د زبدي زوی یعقوب او د هغه ورور یوحنا ولیدل چې په کشتۍ کې ناست وو او خپل جالونه یې تیارول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_19.mp3', '', 1761754199, 1761754199),
(36499, 'Mark 1:20', 'Mark', 1, 20, 'عیسی سمدلاسه هغوی ته نارې کړې او هغوی خپل پلار زبدي د مزدورانو سره په کشتۍ کې پرېښودل او عیسی پسې روان شول. عیسی د یو سړي څخه پېریان وباسي (لوقا ۴‏:‌۳۱‌‏-‌۳۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_20.mp3', '', 1761754199, 1761754199),
(36500, 'Mark 1:21', 'Mark', 1, 21, 'عیسی او شاګردان یې کپرناحوم ته لاړل او کله چې د سبت ورځ راورسېدله، نو عیسی کنیسې ته ننوت او هلته یې تعلیم ورکول پیل کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_21.mp3', '', 1761754199, 1761754199),
(36501, 'Mark 1:22', 'Mark', 1, 22, 'خلک د عیسی په تعلیم حیران شول، ځکه چې هغه د شریعت د عالمانو په شان نه بلکې په پوره اختیار سره هغوی ته تعلیم ورکاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_22.mp3', '', 1761754199, 1761754199),
(36502, 'Mark 1:23', 'Mark', 1, 23, 'ناڅاپه په کنیسه کې یو سړي چې پېریانو نیولی ؤ، په لوړ اواز چیغې ووهلې:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_23.mp3', '', 1761754199, 1761754199),
(36503, 'Mark 1:24', 'Mark', 1, 24, '«ای ناصري عیسی، زمونږ سره څه کار لرې؟ ته راغلی یې چې مونږ تباه کړې؟ زه دې پېژنم چې ته څوک یې، ته د خدای سپېڅلی یې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_24.mp3', '', 1761754199, 1761754199),
(36504, 'Mark 1:25', 'Mark', 1, 25, 'عیسی پېري ته امر وکړ: «غلی شه او د دې سړي څخه راووځه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_25.mp3', '', 1761754199, 1761754199),
(36505, 'Mark 1:26', 'Mark', 1, 26, 'پېري هغه سړي ته سخت ټکان ورکړ او په چیغو چیغو د هغه څخه راووت.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_26.mp3', '', 1761754199, 1761754199),
(36506, 'Mark 1:27', 'Mark', 1, 27, 'ټول خلک دومره حیران شول چې یو له بله یې پوښتنه کوله: «دا څه دي؟ دا خو یو نوی تعلیم دی. هغه په پوره اختیار سره پېریانو ته امر کوي او هغوی یې مني.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_27.mp3', '', 1761754199, 1761754199),
(36507, 'Mark 1:28', 'Mark', 1, 28, 'ډېر زر هغه د جلیل په ټوله سیمه کې مشهور شو. عیسی ډېرو خلکو ته شفا ورکوي (متي ۸‏:‌۱۴‌‏-‌۱۷ او لوقا ۴‏:‌۳۸‌‏-‌۴۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_28.mp3', '', 1761754199, 1761754199),
(36508, 'Mark 1:29', 'Mark', 1, 29, 'بیا عیسی د کنیسې څخه روان شو او د یعقوب او یوحنا سره یوځای د شمعون او اندریاس کور ته لاړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_29.mp3', '', 1761754199, 1761754199),
(36509, 'Mark 1:30', 'Mark', 1, 30, 'د شمعون خواښې تبې نیولې وه او په کټ کې پرته وه. څنګه چې عیسی هلته ورسېده، نو هغوی ورته سمدلاسه د هغې په هکله وویل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_30.mp3', '', 1761754199, 1761754199),
(36510, 'Mark 1:31', 'Mark', 1, 31, 'عیسی ورغی، هغه یې له لاسه ونیوله او مرسته یې ورسره وکړه چې راپورته شي. نو هغه ښځه تبې پرېښودله او د هغوی خدمت یې پیل کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark1_verse_31.mp3', '', 1761754199, 1761754199);